package com.mamtrex.hospital.nutrition;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/diet-orders") public class DietOrderController { private final DietOrderRepository repo; private final AuditService audit; public DietOrderController(DietOrderRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String dietType, @jakarta.validation.constraints.NotBlank String restrictions, @jakarta.validation.constraints.NotBlank String instructions, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public DietOrder create(@Valid @RequestBody Request r){var e=repo.save(new DietOrder(r.patientId(), r.dietType(), r.restrictions(), r.instructions(), r.status()));audit.record("CREATE","DietOrder",e.getId().toString(),"created");return e;} @GetMapping public List<DietOrder> list(){return repo.findAll();} @GetMapping("/{id}") public DietOrder get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("DietOrder not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("DietOrder not found: "+id);repo.deleteById(id);audit.record("DELETE","DietOrder",id.toString(),"deleted");} }
